//! Golden-image regression tests.
//!
//! A deterministic synthetic source is rendered through a fixed recipe and
//! compared, pixel by pixel, against a PNG committed to the repository. If a
//! change to the pipeline alters output, these fail — which is the point.
//!
//! The fixtures are generated by this file, so they carry no third-party
//! licence. To re-bless them after a *deliberate* pipeline change:
//!
//!     UPDATE_GOLDEN=1 cargo test -p lc-core --test golden
//!
//! Re-blessing is a decision, never a convenience: read the diff first.

use lc_core::{Crop, EditRecipe, ExportOptions, ImageBuf, Rotate};
use std::path::PathBuf;

const W: u32 = 64;
const H: u32 = 48;
/// Allowed 8-bit difference per channel. PNG is lossless and the pipeline is
/// deterministic, so this exists only to absorb floating-point drift between
/// CPU targets.
const TOLERANCE: u8 = 1;

fn golden_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("golden")
}

/// Deterministic test chart: a horizontal tonal ramp, a vertical hue sweep, and
/// a deliberately near-clipped corner.
fn chart() -> ImageBuf {
    let mut buf = ImageBuf::new(W, H);
    for y in 0..H {
        for x in 0..W {
            let fx = x as f32 / (W - 1) as f32;
            let fy = y as f32 / (H - 1) as f32;
            let mut rgb = [fx, fy * (1.0 - 0.4 * fx), 1.0 - fy];
            if x > W - 8 && y < 8 {
                rgb = [0.995, 0.99, 0.985];
            }
            if x < 8 && y > H - 8 {
                rgb = [0.004, 0.003, 0.005];
            }
            buf.set(
                x,
                y,
                [
                    lc_core::color::srgb_to_linear(rgb[0]),
                    lc_core::color::srgb_to_linear(rgb[1]),
                    lc_core::color::srgb_to_linear(rgb[2]),
                ],
            );
        }
    }
    buf
}

fn check(name: &str, recipe: EditRecipe) {
    let rendered = lc_core::render(&chart(), &recipe).expect("render must succeed");
    let path = golden_dir().join(format!("{name}.png"));

    if std::env::var_os("UPDATE_GOLDEN").is_some() || !path.exists() {
        std::fs::create_dir_all(golden_dir()).unwrap();
        lc_core::export(
            &rendered,
            &path,
            &ExportOptions {
                overwrite: true,
                ..Default::default()
            },
        )
        .unwrap();
        if std::env::var_os("UPDATE_GOLDEN").is_none() {
            panic!(
                "golden fixture {name}.png was missing and has been written. \
                 Inspect it, commit it, and re-run."
            );
        }
        return;
    }

    let expected = lc_core::decode(&path).expect("golden fixture must decode");
    assert_eq!(
        (expected.meta.width, expected.meta.height),
        (rendered.width, rendered.height),
        "{name}: geometry changed"
    );

    let actual = rendered.to_rgb8();
    let golden = expected.image.to_rgb8();
    let mut worst = 0u8;
    let mut worst_at = (0u32, 0u32);
    let mut differing = 0usize;
    for y in 0..actual.height() {
        for x in 0..actual.width() {
            let a = actual.get_pixel(x, y).0;
            let g = golden.get_pixel(x, y).0;
            for c in 0..3 {
                let d = a[c].abs_diff(g[c]);
                if d > 0 {
                    differing += 1;
                }
                if d > worst {
                    worst = d;
                    worst_at = (x, y);
                }
            }
        }
    }
    assert!(
        worst <= TOLERANCE,
        "{name}: output drifted from the golden image. \
         Worst difference {worst}/255 at {worst_at:?}, {differing} sample(s) differ. \
         If this change was intended, re-run with UPDATE_GOLDEN=1 and commit the new fixture."
    );
}

#[test]
fn golden_neutral() {
    check("neutral", EditRecipe::default());
}

#[test]
fn golden_exposure_up_one_stop() {
    let mut r = EditRecipe::default();
    r.adjustments.exposure_ev = 1.0;
    check("exposure_up", r);
}

#[test]
fn golden_tone_shaping() {
    let mut r = EditRecipe::default();
    r.adjustments.contrast = 0.35;
    r.adjustments.shadows = 0.5;
    r.adjustments.highlights = -0.4;
    check("tone", r);
}

#[test]
fn golden_white_balance_warm() {
    let mut r = EditRecipe::default();
    r.adjustments.temperature = 0.5;
    r.adjustments.tint = -0.2;
    check("warm", r);
}

#[test]
fn golden_colour_strength() {
    let mut r = EditRecipe::default();
    r.adjustments.saturation = 0.4;
    r.adjustments.vibrance = 0.6;
    check("colour", r);
}

#[test]
fn golden_geometry_crop_and_rotate() {
    let mut r = EditRecipe::default();
    r.crop = Some(Crop {
        x: 8,
        y: 4,
        width: 40,
        height: 30,
    });
    r.rotate = Rotate::Cw270;
    check("geometry", r);
}

#[test]
fn golden_everything_at_once() {
    let mut r = EditRecipe::default();
    r.adjustments.exposure_ev = -0.5;
    r.adjustments.contrast = 0.25;
    r.adjustments.highlights = -0.3;
    r.adjustments.shadows = 0.35;
    r.adjustments.temperature = 0.3;
    r.adjustments.tint = 0.1;
    r.adjustments.saturation = 0.2;
    r.adjustments.vibrance = 0.4;
    r.crop = Some(Crop {
        x: 2,
        y: 2,
        width: 60,
        height: 44,
    });
    r.rotate = Rotate::Cw90;
    check("combined", r);
}
